package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result); // 1*64 + 2*8 + 3 = 64 + 16 + 3 = 83
    }

    @Test
    public void testParseOctal_LeadingSpaces() {
        byte[] buffer = "   000755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(493L, result); // 7*64 + 5*8 + 5 = 448 + 40 + 5 = 493
    }

    @Test
    public void testParseOctal_TrailingSpacesAndNulls() {
        // The logic: trailer = buffer[end-0]. 
        // Note: the provided code has a potential IndexOutOfBounds if end is buffer.length
        // But based on the logic provided:
        byte[] buffer = "000100  \0\0".getBytes();
        // length 10. end = 10. trailer = buffer[10] -> This would throw if buffer.length is 10.
        // Assuming buffer is large enough for the 'end' index accessed.
        byte[] largeBuffer = new byte[15];
        System.arraycopy("000100  \0\0".getBytes(), 0, largeBuffer, 0, 10);

        long result = TarUtils.parseOctal(largeBuffer, 0, 10);
        assertEquals(64L, result);
    }

    @Test
    public void testParseOctal_AllZeros() {
        byte[] buffer = "000000".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(0L, result);
    }

    @Test
    public void testParseOctal_FirstByteIsZero() {
        // if (buffer[start] == 0) return 0L;
        byte[] buffer = new byte[5];
        buffer[0] = 0;
        buffer[1] = '1';
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "0".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidOctalDigit() {
        byte[] buffer = "000899".getBytes(); // 8 and 9 are not octal
        TarUtils.parseOctal(buffer, 0, 6);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonDigitChar() {
        byte[] buffer = "000A12".getBytes();
        TarUtils.parseOctal(buffer, 0, 6);
    }

    @Test
    public void testParseOctal_WithOffset() {
        byte[] buffer = "junk0007".getBytes();
        // offset 4, length 4 -> "0007"
        long result = TarUtils.parseOctal(buffer, 4, 4);
        assertEquals(7L, result);
    }

    @Test
    public void testParseOctal_ComplexTrailing() {
        // Testing the while loop for trimming: trailer = buffer[end-0]
        // and trailer = buffer[end-1]
        byte[] buffer = "000123 \0 ".getBytes();
        // length is 9. end is 9.
        // trailer = buffer[9] -> must ensure buffer size allows this.
        byte[] padded = new byte[11];
        System.arraycopy("000123 \0 ".getBytes(), 0, padded, 0, 9);
        padded[9] = ' ';
        padded[10] = ' ';

        long result = TarUtils.parseOctal(padded, 0, 10);
        assertEquals(83L, result);
    }
}
